# status.sh — run all registered status reporters in order.
#
# Generated by the status subsystem. The reporter list below is baked in at
# render time from the STATUSES fact -- not globbed -- so ordering is deliberate:
#   - producer generators append their purpose-built reporters;
#   - gen_kernel appends status-sysctl.ts / status-modules.ts / status-sysfs.ts;
#   - gen_status_proc appends the reporters selected by STATUS_PROC;
#   - the status subsystem appends status-dirs.sh when STATUS_DIRS is set.
#
# Each reporter runs with "$@" passed through, under a section header. String
# records retain the historical 0 clean / 1 drift / 2 not-applicable contract.
# A structured `{name, args, exit2: error}` record may bind fixed arguments and
# marks exit 2 as evaluation failure, without generating another wrapper file.
#
# This is a compfuzor _bin body: files/_bin supplies the shebang,
# `set -euo pipefail`, env loading, and option restoration.

# ordered reporters, baked in at render time from STATUSES
REPORTERS=(
{% for r in STATUSES | default([]) %}  {{ r.name if r is mapping else r }}
{% endfor %})
ERROR2=(
{% for r in STATUSES | default([]) %}  {{ 1 if r is mapping and r.exit2 | default('') == 'error' else 0 }}
{% endfor %})

overall=0
for i in "${!REPORTERS[@]}"; do
  r="${REPORTERS[$i]}"
  script="$DIR/bin/$r"
  [ -x "$script" ] || continue
  printf '\n=== %s ===\n' "$r"
  reporter_args=()
  case "$i" in
{% for r in STATUSES | default([]) %}
    {{ loop.index0 }}) reporter_args=({% if r is mapping %}{% for arg in r.args | default([]) | normalize(to='list') %} {{ arg | quote }}{% endfor %}{% endif %}) ;;
{% endfor %}
  esac
  code=0
  "$script" "${reporter_args[@]}" "$@" || code=$?
  case "$code" in
    0) ;;
    2) [ "${ERROR2[$i]}" = 0 ] || overall=1 ;;
    *) overall=1 ;;
  esac
done

exit "$overall"
